+    return property_declarations_;
+  }
+  const std::vector<Label>& Labels() const { return labels_; }
+  const std::vector<GraphElementTable>& NodeTables() const {
+    return node_tables_;
+  }
+  const std::vector<GraphElementTable>& EdgeTables() const {
+    return edge_tables_;
+  }
