+      : validate_(validate), validate_update_(validate_update) {}
+  PropertyGraph(const PropertyGraph&) = default;
+  std::unique_ptr<SchemaNode> ShallowClone() const override {
+    return absl::WrapUnique(new PropertyGraph(*this));
+  }
