+void VisitAlterLocalityGroupNode(const SimpleNode* node,
+                                 AlterLocalityGroup* alter_locality_group,
+                                 std::vector<std::string>* errors) {
+  CheckNode(node, JJTALTER_LOCALITY_GROUP_STATEMENT);
