+    ZETASQL_EXPECT_OK(MultiInsert("messages",
+                          {"user_id", "thread_id", "message_id", "subject"},
+                          {{1, 1, 1, "a code review"},
+                           {1, 1, 2, "Re: a code review"},
+                           {1, 2, 1, "Congratulations Douglas"},
+                           {1, 3, 1, "Reminder to write feedback"},
+                           {1, 4, 1, "Meeting this week"},
+                           {2, 1, 1, "Lunch today?"},
